def find_path(graph, start, goal):
    def depth_first_search(graph, path, visited):
        if start in visited:
            return None
        if start == goal:
            return path + [goal]

        visited.add(start)
        for neighbor in graph[start]:
            result = depth_first_search(graph, path + [start], visited)
            if result:
                return result
        return None

    def breadth_first_search(graph, path, visited):
        queue = [(start, [start])]
        while queue:
            (node, path) = queue.pop(0)
            if node in visited:
                continue
            if node == goal:
                return path + [goal]
            visited.add(node)
            for neighbor in graph[node]:
                queue.append((neighbor, path + [node]))
        return None

    visited_dfs = set()
    visited_bfs = set()

    dfs_result = depth_first_search(graph, [], visited_dfs)
    bfs_result = breadth_first_search(graph, [], visited_bfs)

    if not dfs_result and not bfs_result:
        return None
    else:
        return dfs_result if dfs_result else bfs_result

