def find_path(graph, start, goal):
    """
    Finds a path from start to goal node in the given graph using a path search algorithm.
    The graph is represented as a dictionary where each key is a node and the value is a list of neighboring nodes.
    If a path exists from start to goal, returns a list of nodes that make up that path.
    Otherwise, returns None.
    """
    if start == goal:
        return [start]  # If start and goal are the same, return the start node.

    visited = set()  # A set to keep track of visited nodes.
    path = {start: [start]}  # A dictionary to store the path to each node.

    while path:
        current = None
        for node in path:
            if node not in visited:
                current = node
                break
        if current is None:
            return None  # There is no path from start to goal.

        visited.add(current)
        if current == goal:
            return path[current]

        for neighbor in graph[current]:
            if neighbor not in visited:
                path[neighbor] = path[current] + [neighbor]

    return None
